const browserPluginRoot = process.env.CF_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
if (!browserPluginRoot) throw new Error('Browser plugin root is unavailable in the node_repl host');
const { join } = await import('node:path');
const { pathToFileURL } = await import('node:url');
const browserClientUrl = pathToFileURL(join(browserPluginRoot, 'scripts', 'browser-client.mjs')).href;
const { setupBrowserRuntime } = await import(browserClientUrl);
await setupBrowserRuntime({ globals: globalThis });
const browser = await agent.browsers.get('iab');
const multitabUrlA = new URL('/a', '{{browserFixtureUrl}}').href;
const multitabUrlB = new URL('/b', '{{browserFixtureUrl}}').href;
const multitabA = await browser.tabs.new();
await multitabA.goto(multitabUrlA);
await multitabA.playwright.getByLabel('State').fill('alpha-turn-1');
const multitabB = await browser.tabs.new();
await multitabB.goto(multitabUrlB);
await multitabB.playwright.getByLabel('State').fill('beta-turn-1');
await browser.tabs.finalize({ keep: [{ tab: multitabA, status: 'handoff' }] });
const tabsAfterFinalize = await browser.tabs.list();
const turnOneOk = tabsAfterFinalize.length === 2 && tabsAfterFinalize.some((info) => info.id === multitabA.id) && tabsAfterFinalize.some((info) => info.id === multitabB.id);
({ marker: turnOneOk ? 'E2E_BROWSER_USE_MULTITAB_TURN1_OK' : 'E2E_BROWSER_USE_MULTITAB_TURN1_FAILED', aId: multitabA.id, bId: multitabB.id, tabsAfterFinalize });

const browserPluginRoot = process.env.CF_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
if (!browserPluginRoot) throw new Error('Browser plugin root is unavailable in the node_repl host');
const { join } = await import('node:path');
