const browserClientUrl = pathToFileURL(join(browserPluginRoot, 'scripts', 'browser-client.mjs')).href;
const { setupBrowserRuntime } = await import(browserClientUrl);
await setupBrowserRuntime({ globals: globalThis });
const browser = await agent.browsers.get('iab');
const tabs = await browser.tabs.list();
const matchesA = tabs.filter((info) => new URL(info.url).pathname === '/a');
const matchesB = tabs.filter((info) => new URL(info.url).pathname === '/b');
if (matchesA.length !== 1 || matchesB.length !== 1) throw new Error('Expected one controlled A tab and one controlled B tab');
({ marker: 'E2E_BROWSER_USE_MULTITAB_LIST_OK', e2eBrowserTabAId: matchesA[0].id, e2eBrowserTabBId: matchesB[0].id, tabs });

const browserPluginRoot = process.env.CF_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
if (!browserPluginRoot) throw new Error('Browser plugin root is unavailable in the node_repl host');
const { join } = await import('node:path');
const { pathToFileURL } = await import('node:url');
const browserClientUrl = pathToFileURL(join(browserPluginRoot, 'scripts', 'browser-client.mjs')).href;
const { setupBrowserRuntime } = await import(browserClientUrl);
await setupBrowserRuntime({ globals: globalThis });
const browser = await agent.browsers.get('iab');
const aInfo = { id: '{{latestBrowserTabAId}}' };
const bInfo = { id: '{{latestBrowserTabBId}}' };
const before = await browser.tabs.list();
if (!before.some((info) => info.id === aInfo.id) || !before.some((info) => info.id === bInfo.id)) throw new Error('Tool-result stable tab ids no longer exist');
const multitabA = await browser.tabs.get(aInfo.id);
const stateBeforeA = await multitabA.playwright.getByRole('status').innerText();
await multitabA.playwright.getByLabel('State').fill('alpha-turn-2');
const multitabB = await browser.tabs.get(bInfo.id);
await multitabB.close();
await browser.tabs.get(aInfo.id);
const after = await browser.tabs.list();
const turnTwoOk = before.length === 2 && stateBeforeA === 'alpha-turn-1' && after.length === 1 && after[0]?.id === aInfo.id && after[0]?.active === true && !after.some((info) => info.id === bInfo.id);
({ marker: turnTwoOk ? 'E2E_BROWSER_USE_MULTITAB_TURN2_OK' : 'E2E_BROWSER_USE_MULTITAB_TURN2_FAILED', beforeCount: before.length, afterCount: after.length, aId: aInfo.id, bId: bInfo.id, stateBeforeA, after });
